Indeed, I fixed it. Since there are so many of items, so I changed it to iterate, but is this okay for null checking?
```cpp
Size2 CheckBox::get_icon_size() const {
	Vector<Ref<Texture2D>> icons;
	icons.push_back(Control::get_theme_icon(SNAME("checked")));
	icons.push_back(Control::get_theme_icon(SNAME("unchecked")));
	icons.push_back(Control::get_theme_icon(SNAME("radio_checked")));
	icons.push_back(Control::get_theme_icon(SNAME("radio_unchecked")));
	icons.push_back(Control::get_theme_icon(SNAME("checked_disabled")));
	icons.push_back(Control::get_theme_icon(SNAME("unchecked_disabled")));
	icons.push_back(Control::get_theme_icon(SNAME("radio_checked_disabled")));
	icons.push_back(Control::get_theme_icon(SNAME("radio_unchecked_disabled")));

	Size2 tex_size = Size2(0, 0);
	for (int i = 0; i < icons.size(); ++i) {
		if (icons[i].is_null()) {
			continue;
		}
		tex_size = Size2(MAX(tex_size.width, icons[i]->get_width()), MAX(tex_size.height, icons[i]->get_height()));
	}
	return tex_size;
}
```
